// client/src/features/dashboard/attendee/JoinSession.jsx
import React, { useEffect, useRef, useState } from 'react';
import { useLocation, Link } from 'react-router-dom';
import '../../../styles/GlobalStyles.css';

const JoinSession = () => {
  const { search }    = useLocation();
  const roomName      = new URLSearchParams(search).get('link') || 'DefaultRoom';
  const videoRef      = useRef(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    let stream;

    // ask for camera+mic, then attach to the video element
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(s => {
        stream = s;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      })
      .catch(err => {
        console.error('Media error:', err);
        setError('Unable to access camera/microphone.');
      });

    // cleanup on unmount: stop all tracks
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, []); // run once

  return (
    <div className="container">
      <div className="card" style={{ minHeight: '650px' }}>
        <h2>Live Session: <em>{roomName}</em></h2>

        {error && <p style={{ color: 'red' }}>{error}</p>}

        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={{
            width: '100%',
            height: '600px',
            background: '#000',
            borderRadius: '8px'
          }}
        />

        <Link to="/attendee/dashboard">
          <button className="btn" style={{ marginTop: '1rem' }}>
            Back to Dashboard
          </button>
        </Link>
      </div>
    </div>
  );
};

export default JoinSession;
